import{_ as e,H as r,f as o,i as a}from"./chunks/framework.Cvt1eIE0.js";const p=JSON.parse('{"title":"收藏｜X 上关于 Flutter 性能的高赞讨论精华","description":"","frontmatter":{"title":"收藏｜X 上关于 Flutter 性能的高赞讨论精华","date":"2026-05-20T00:00:00.000Z","category":"收藏","tags":["Flutter","收藏","X"],"excerpt":"整理开发者社区关于 Impeller、重建优化与真机 Profiling 的共识与争议，附可执行检查清单。"},"headers":[],"relativePath":"posts/收藏/x-flutter-performance-discussions.md","filePath":"posts/收藏/x-flutter-performance-discussions.md"}'),l={name:"posts/收藏/x-flutter-performance-discussions.md"};function i(d,t,n,s,c,u){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="x-上关于-flutter-性能的讨论精华" tabindex="-1">X 上关于 Flutter 性能的讨论精华 <a class="header-anchor" href="#x-上关于-flutter-性能的讨论精华" aria-label="Permalink to &quot;X 上关于 Flutter 性能的讨论精华&quot;">​</a></h1><blockquote><p>本文为<strong>编辑整理</strong>，归纳公开技术社区（含 X/Twitter、Mastodon 技术圈）常见观点，非单条推文转载。具体作者与链接因时效未逐一列出，建议结合官方文档验证。</p></blockquote><h2 id="_1-「卡顿」先分三类" tabindex="-1">1. 「卡顿」先分三类 <a class="header-anchor" href="#_1-「卡顿」先分三类" aria-label="Permalink to &quot;1. 「卡顿」先分三类&quot;">​</a></h2><p>社区高频提醒：先区分 <strong>构建（build）</strong>、<strong>布局（layout）</strong>、<strong>绘制（paint）</strong> 三类成本。DevTools 里看 <code>build</code> 次数飙升，优先 <code>const</code> 与状态下沉；GPU 线程热，查 <code>RepaintBoundary</code> 与图片解码尺寸。</p><h2 id="_2-impeller-不是万能药" tabindex="-1">2. Impeller 不是万能药 <a class="header-anchor" href="#_2-impeller-不是万能药" aria-label="Permalink to &quot;2. Impeller 不是万能药&quot;">​</a></h2><p>2024–2025 年讨论里，Impeller 被寄予「消灭着色器编译 jank」的期望，但复杂矢量与模糊仍可能吃 GPU。整理帖共识：<strong>在目标机型 profile</strong>，不要只看发布会帧率。</p><h2 id="_3-列表与图片是移动端真凶" tabindex="-1">3. 列表与图片是移动端真凶 <a class="header-anchor" href="#_3-列表与图片是移动端真凶" aria-label="Permalink to &quot;3. 列表与图片是移动端真凶&quot;">​</a></h2><p>多条高互动帖指向同一结论：</p><ul><li><code>ListView.builder</code> + 固定 <code>itemExtent</code> 当可行时</li><li>网络图必须限制解码宽高（<code>cacheWidth</code> / <code>cacheHeight</code>）</li><li>避免在滚动回调里同步 IO</li></ul><h2 id="_4-可执行的每周-profiling-仪式" tabindex="-1">4. 可执行的每周 Profiling 仪式 <a class="header-anchor" href="#_4-可执行的每周-profiling-仪式" aria-label="Permalink to &quot;4. 可执行的每周 Profiling 仪式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>步骤</th><th>动作</th></tr></thead><tbody><tr><td>周一</td><td><code>flutter run --profile</code> 走核心路径</td></tr><tr><td>合并前</td><td>对比 <code>build</code> 热点是否新增</td></tr><tr><td>发布前</td><td>低端 Android 实机 10 分钟 monkey</td></tr></tbody></table><h2 id="_5-社区争议-要不要「极致」优化" tabindex="-1">5. 社区争议：要不要「极致」优化 <a class="header-anchor" href="#_5-社区争议-要不要「极致」优化" aria-label="Permalink to &quot;5. 社区争议：要不要「极致」优化&quot;">​</a></h2><p>一派认为应像原生一样抠每帧；另一派认为业务迭代优先，<strong>只在用户可感知处优化</strong>。整理建议是：为关键转化路径设性能预算（例如首屏 &lt; 1.2s），其余遵循 lint 即可。</p><hr><p>若你只收藏一篇 Flutter 性能相关讨论，建议把<strong>可复现的 Profiling 流程</strong>写在团队 Wiki，比收藏推文链接更耐用。</p>',15)])])}const f=e(l,[["render",i]]);export{p as __pageData,f as default};
